  const response={result:path==='/proposals/publish'||path==='/rollback'?publication():proposal(),operationId:'fixture-operation-'+key,replayed:false};receipts.set(key,response);if(options.unknownOnce&&!lost){lost=true;return route.abort('failed');}return reply(response);
