test('configuration Search independently validates its qualified budget and preserves input after server rejection',async({page},info)=>{
 test.setTimeout(60_000);const server=await fixture(page),queries:Record<string,unknown>[]=[],requests:string[]=[];
 page.on('request',request=>{if(new URL(request.url()).pathname.startsWith('/identity/configuration/'))requests.push(request.url());});
 await page.route('**/identity/configuration/proposals/search',async route=>{const body=route.request().postDataJSON() as Record<string,unknown>;queries.push(body);if(String(body.search).startsWith('fixture-unavailable-')){expect(route.request().headers()['x-tunner-csrf']).toBe('fixture-configuration-csrf');return route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error_code:'DEPENDENCY_UNAVAILABLE',detail:'fixture-private-server-detail'})});}return route.fallback();});
 for(const width of [1440,768,390])await test.step('Search at '+width,async()=>{
  await page.setViewportSize({width,height:width===390?844:1024});await select(page,'Authentication',false);const search=page.getByLabel('Search candidates',{exact:true}),submit=page.getByRole('button',{name:'Search candidates',exact:true}),error=page.locator('#configuration-search-error');await expect(search).toBeEnabled();await expect(search).toHaveAttribute('maxlength','64');await search.evaluate(input=>input.removeAttribute('maxlength'));
  const beforeQueries=queries.length,beforeRequests=requests.length;await search.fill('x'.repeat(65));await expect(search).toHaveValue('x'.repeat(65));await search.press('Tab');await expect(search).toHaveAttribute('aria-invalid','true');await expect(search).toHaveAttribute('aria-describedby',/(?:^| )configuration-search-error(?: |$)/);await expect(error).toBeVisible();await expect(error).toHaveText(labels.validationSummary);await expect(error).not.toContainText(labels.invalidNumber);await submit.focus();await expect(submit).toBeFocused();await page.keyboard.press('Enter');await expect(search).toBeFocused();expect(queries).toHaveLength(beforeQueries);expect(requests).toHaveLength(beforeRequests);expect(server.writes).toHaveLength(0);await expect(page.locator(':invalid')).toHaveCount(0);
  expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath(`configuration-search-error-${width}.png`),fullPage:true});
  const bounded='s'.repeat(64);await search.fill(bounded);await search.press('Tab');await expect(search).not.toHaveAttribute('aria-invalid','true');await expect(error).toHaveCount(0);await submit.focus();await page.keyboard.press('Enter');await expect.poll(()=>queries.length).toBe(beforeQueries+1);expect(queries.at(-1)).toEqual({scope:scopes.Authentication,search:bounded,pageSize:5,offset:0});await expect(search).toBeEnabled();await expect(search).toHaveValue(bounded);
  const unavailable='fixture-unavailable-'+width;await search.fill(unavailable);await submit.focus();await page.keyboard.press('Enter');await expect.poll(()=>queries.length).toBe(beforeQueries+2);expect(queries.at(-1)).toEqual({scope:scopes.Authentication,search:unavailable,pageSize:5,offset:0});await expect(page.getByText(labels.unavailable,{exact:true})).toBeVisible();await expect(search).toHaveValue(unavailable);await expect(page.getByText('fixture-private-server-detail',{exact:true})).toHaveCount(0);expect(server.writes).toHaveLength(0);expect(new URL(page.url()).search).toBe('');expect(new URL(page.url()).hash).toBe('');expect(page.url()).not.toContain(unavailable);
 });
});
